        default Value applyValue(Value...arguments)throws Throwable{Object[] javaArgs=new Object[arguments.length];for(int i=0;i<arguments.length;i++)javaArgs[i]=Values.toJava(arguments[i]);return Values.fromJava(apply(javaArgs),ValueAdapters.DEFAULT);}
